import{_ as e,o as t,c as d,a2 as s}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"Grenade Count","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/enums/player-traits/grenade-count.md","filePath":"ja/language/enums/player-traits/grenade-count.md"}'),o={name:"ja/language/enums/player-traits/grenade-count.md"};function n(r,a,l,c,p,g){return t(),d("div",null,[...a[0]||(a[0]=[s(`<h1 id="grenade-count" tabindex="-1">Grenade Count <a class="header-anchor" href="#grenade-count" aria-label="Permalink to &quot;Grenade Count&quot;">​</a></h1><p><a href="/MegaloEvolved/beta/docs/ja/language/enums/player-traits">プレイヤートレイト</a> enum の <code>initial_grenades</code> フィールド用の値構文です。<a href="/MegaloEvolved/beta/docs/ja/language/elements/game-options/player-traits"><code>player_traits</code></a> ブロック内、および <a href="/MegaloEvolved/beta/docs/ja/language/elements/game-options"><code>game_options</code></a> の <code>override base_player_traits</code>（など）で使います。</p><p>ManagedMegalo は単一トークン、または個数＋グレネード種別を受け付けます。Reach スクリプトはワイヤ上で <strong>frag</strong> と <strong>plasma</strong> の個数のみを使います（<code>each</code> は両方を同数に設定します）。</p><h2 id="特殊値" tabindex="-1">特殊値 <a class="header-anchor" href="#特殊値" aria-label="Permalink to &quot;特殊値&quot;">​</a></h2><table tabindex="0"><thead><tr><th>値</th><th>効果</th></tr></thead><tbody><tr><td><code>none</code></td><td>開始グレネードなし</td></tr><tr><td><code>default</code></td><td>マップのデフォルトグレネードロードアウトを使用</td></tr></tbody></table><h2 id="個数形式" tabindex="-1">個数形式 <a class="header-anchor" href="#個数形式" aria-label="Permalink to &quot;個数形式&quot;">​</a></h2><p>個数は <strong>1–4</strong> である必要があります。種別は <code>frag</code>、<code>plasma</code>、または <code>each</code> です。</p><table tabindex="0"><thead><tr><th>構文</th><th>開始グレネード</th></tr></thead><tbody><tr><td><code>1 frag</code></td><td>frag 1 個</td></tr><tr><td><code>2 frag</code></td><td>frag 2 個</td></tr><tr><td><code>3 frag</code></td><td>frag 3 個</td></tr><tr><td><code>4 frag</code></td><td>frag 4 個</td></tr><tr><td><code>1 plasma</code></td><td>plasma 1 個</td></tr><tr><td><code>2 plasma</code></td><td>plasma 2 個</td></tr><tr><td><code>3 plasma</code></td><td>plasma 3 個</td></tr><tr><td><code>4 plasma</code></td><td>plasma 4 個</td></tr><tr><td><code>1 each</code></td><td>frag 1 個と plasma 1 個</td></tr><tr><td><code>2 each</code></td><td>frag 2 個と plasma 2 個</td></tr><tr><td><code>3 each</code></td><td>frag 3 個と plasma 3 個</td></tr><tr><td><code>4 each</code></td><td>frag 4 個と plasma 4 個</td></tr></tbody></table><p>不等な frag と plasma の個数を混ぜるには、<strong>別々の行</strong>を使います — 各行がロードアウトの片側を更新します:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">override base_player_traits</span></span>
<span class="line"><span class="megalo-text">	initial_grenades </span><span class="megalo-number">1</span><span class="megalo-text"> frag</span></span>
<span class="line"><span class="megalo-text">	initial_grenades </span><span class="megalo-number">1</span><span class="megalo-text"> plasma</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">player_traits infected_traits</span></span>
<span class="line"><span class="megalo-text">	initial_grenades none</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p><a href="/MegaloEvolved/beta/docs/ja/language/object-lists"><code>grenades.txt</code></a> のグレネード種別（spike、firebomb など）はここでは無効です。Megalo パーサが受け付けるのは <code>frag</code>、<code>plasma</code>、<code>each</code> のみです。</p><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/enums/player-traits">プレイヤートレイト</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/game-options/player-traits">player_traits</a></li></ul>`,14)])])}const h=e(o,[["render",n]]);export{m as __pageData,h as default};
